import { test, expect } from '@playwright/test';

test.describe('Email Field Inline Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should show validation error for invalid email', async ({ page }) => {
    await page.getByLabel('Email').fill('invalid-email');
    await page.getByLabel('Email').blur();
    const errorMessage = await page.getByText('Please enter a valid email address.');
    await expect(errorMessage).toBeVisible();
  });

  test('should not show validation error for valid email', async ({ page }) => {
    await page.getByLabel('Email').fill('valid.email@example.com');
    await page.getByLabel('Email').blur();
    const errorMessage = page.getByText('Please enter a valid email address.');
    await expect(errorMessage).not.toBeVisible();
  });
});
